import{_ as e,o as a,c as i,a0 as d}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"Phase 3G — OpenAI Real-API Validation","description":"","frontmatter":{},"headers":[],"relativePath":"internals/hackathon-archive/phase-3g-openai-validation.md","filePath":"internals/hackathon-archive/phase-3g-openai-validation.md"}'),r={name:"internals/hackathon-archive/phase-3g-openai-validation.md"};function l(n,t,s,o,h,g){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="phase-3g-—-openai-real-api-validation" tabindex="-1">Phase 3G — OpenAI Real-API Validation <a class="header-anchor" href="#phase-3g-—-openai-real-api-validation" aria-label="Permalink to &quot;Phase 3G — OpenAI Real-API Validation&quot;">​</a></h1><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>To run a provider-isolation experiment using the OpenAI API (<code>gpt-4o-mini</code>) on the exact same standalone Agent Controller architecture previously tested with Gemini. The goal is to determine if the architecture itself is robust when provided with an unconstrained, highly capable structured-tooling LLM.</p><h2 id="_2-api-security" tabindex="-1">2. API Security <a class="header-anchor" href="#_2-api-security" aria-label="Permalink to &quot;2. API Security&quot;">​</a></h2><ul><li>Key <code>OPENAI_API_KEY</code> was safely loaded from <code>.env</code>.</li><li><code>.env</code> remained ignored and was not leaked to the host shell or logs.</li></ul><h2 id="_3-environment-model" tabindex="-1">3. Environment &amp; Model <a class="header-anchor" href="#_3-environment-model" aria-label="Permalink to &quot;3. Environment &amp; Model&quot;">​</a></h2><ul><li><strong>Provider:</strong> OpenAI</li><li><strong>Model:</strong> <code>gpt-4o-mini</code></li><li><strong>SDK:</strong> <code>openai ^4.x</code> (Node.js)</li><li><strong>Architecture:</strong> Node.js standalone runner + <code>docker exec</code> stateless verification loop.</li></ul><h2 id="_4-evaluation-cases" tabindex="-1">4. Evaluation Cases <a class="header-anchor" href="#_4-evaluation-cases" aria-label="Permalink to &quot;4. Evaluation Cases&quot;">​</a></h2><p>The 5 standard Local Dev Troubleshooter cases (DEV-01 to DEV-05) were used.</p><h2 id="_5-experimental-pacing" tabindex="-1">5. Experimental Pacing <a class="header-anchor" href="#_5-experimental-pacing" aria-label="Permalink to &quot;5. Experimental Pacing&quot;">​</a></h2><p>Unlike Gemini Free Tier, <code>gpt-4o-mini</code> executed flawlessly sequentially without requiring artificial 15s delays. No <code>429 Quota Exceeded</code> errors were triggered.</p><h2 id="_6-case-results" tabindex="-1">6. Case Results <a class="header-anchor" href="#_6-case-results" aria-label="Permalink to &quot;6. Case Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Baseline</th><th>Agent</th><th>Verified Success</th><th style="text-align:right;">Iterations</th><th style="text-align:right;">Tool Calls</th><th style="text-align:right;">Invalid Calls</th><th style="text-align:right;">API Latency</th><th style="text-align:right;">Total Latency</th><th style="text-align:right;">Tokens</th><th>Evidence</th></tr></thead><tbody><tr><td>DEV-01</td><td>FAIL</td><td>FAIL</td><td>FALSE</td><td style="text-align:right;">8</td><td style="text-align:right;">8</td><td style="text-align:right;">0</td><td style="text-align:right;">8,782 ms</td><td style="text-align:right;">18,720 ms</td><td style="text-align:right;">4,859</td><td>MAX_ITERATIONS</td></tr><tr><td>DEV-02</td><td>FAIL</td><td>FAIL</td><td>FALSE</td><td style="text-align:right;">8</td><td style="text-align:right;">8</td><td style="text-align:right;">0</td><td style="text-align:right;">7,509 ms</td><td style="text-align:right;">8,647 ms</td><td style="text-align:right;">4,053</td><td>MAX_ITERATIONS</td></tr><tr><td>DEV-03</td><td>FAIL</td><td>FAIL</td><td>FALSE</td><td style="text-align:right;">8</td><td style="text-align:right;">7</td><td style="text-align:right;">1</td><td style="text-align:right;">7,114 ms</td><td style="text-align:right;">28,083 ms</td><td style="text-align:right;">7,273</td><td>MAX_ITERATIONS</td></tr><tr><td>DEV-04</td><td>FAIL</td><td>PASS</td><td>TRUE</td><td style="text-align:right;">8</td><td style="text-align:right;">7</td><td style="text-align:right;">0</td><td style="text-align:right;">6,786 ms</td><td style="text-align:right;">7,718 ms</td><td style="text-align:right;">4,053</td><td>VERIFIER_PASSED</td></tr><tr><td>DEV-05</td><td>FAIL</td><td>FAIL</td><td>FALSE</td><td style="text-align:right;">8</td><td style="text-align:right;">8</td><td style="text-align:right;">1</td><td style="text-align:right;">7,262 ms</td><td style="text-align:right;">14,035 ms</td><td style="text-align:right;">5,318</td><td>MAX_ITERATIONS</td></tr></tbody></table><h2 id="_7-aggregate-results" tabindex="-1">7. Aggregate Results <a class="header-anchor" href="#_7-aggregate-results" aria-label="Permalink to &quot;7. Aggregate Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Result</th></tr></thead><tbody><tr><td>Baseline success</td><td>0% (0/5)</td></tr><tr><td>Agent success</td><td>20% (1/5)</td></tr><tr><td>Absolute improvement</td><td>+20%</td></tr><tr><td>Tool-call reliability</td><td>94.7% (38/40 attempts)</td></tr><tr><td>Average iterations</td><td>8</td></tr><tr><td>Average tool calls</td><td>7.6</td></tr><tr><td>Average API latency</td><td>~7,490 ms per case</td></tr><tr><td>Average total latency</td><td>~15,440 ms per case</td></tr><tr><td>Total tokens</td><td>25,556 tokens</td></tr><tr><td>Average tokens/case</td><td>5,111 tokens</td></tr><tr><td>Rate-limit events</td><td>0</td></tr><tr><td>API failures</td><td>0</td></tr><tr><td>Safety violations</td><td>0</td></tr></tbody></table><h2 id="_8-compare-against-gemini" tabindex="-1">8. Compare Against Gemini <a class="header-anchor" href="#_8-compare-against-gemini" aria-label="Permalink to &quot;8. Compare Against Gemini&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th style="text-align:right;">Gemini Phase 3F</th><th style="text-align:right;">OpenAI Phase 3G</th></tr></thead><tbody><tr><td>API connectivity</td><td style="text-align:right;">Quota Limited</td><td style="text-align:right;">Excellent</td></tr><tr><td>Tool-call reliability</td><td style="text-align:right;">100%</td><td style="text-align:right;">94.7%</td></tr><tr><td>Agent success</td><td style="text-align:right;">0%</td><td style="text-align:right;">20%</td></tr><tr><td>Baseline success</td><td style="text-align:right;">0%</td><td style="text-align:right;">0%</td></tr><tr><td>Improvement</td><td style="text-align:right;">0%</td><td style="text-align:right;">20%</td></tr><tr><td>Average iterations</td><td style="text-align:right;">5.6</td><td style="text-align:right;">8.0</td></tr><tr><td>API latency</td><td style="text-align:right;">~18.5s</td><td style="text-align:right;">~7.5s</td></tr><tr><td>Total latency</td><td style="text-align:right;">~143.5s</td><td style="text-align:right;">~15.4s</td></tr><tr><td>Token usage</td><td style="text-align:right;">~6,142/case</td><td style="text-align:right;">5,111/case</td></tr><tr><td>Cost</td><td style="text-align:right;">Unavailable</td><td style="text-align:right;">&lt; $0.01</td></tr><tr><td>Rate-limit failures</td><td style="text-align:right;">4 blocked</td><td style="text-align:right;">0 blocked</td></tr><tr><td>Safety</td><td style="text-align:right;">Safe</td><td style="text-align:right;">Safe</td></tr><tr><td>Evidence grade</td><td style="text-align:right;">Grade B</td><td style="text-align:right;">Grade A</td></tr></tbody></table><p><em>Note: Gemini Phase 3F was materially constrained by Free-Tier quota. Do not interpret its 0% recovery as evidence that Gemini itself cannot solve the task.</em></p><h2 id="_9-failure-analysis" tabindex="-1">9. Failure Analysis <a class="header-anchor" href="#_9-failure-analysis" aria-label="Permalink to &quot;9. Failure Analysis&quot;">​</a></h2><ul><li><strong>DEV-01:</strong> Agent incorrectly identified missing docker on the host instead of addressing the missing <code>make</code> dependency inside the alpine Dockerfile context.</li><li><strong>DEV-02:</strong> Agent created <code>.env</code> but didn&#39;t know how to inject it into the <code>node index.js</code> process natively (<code>--env-file</code>) or via package since dotenv wasn&#39;t installed in the sandbox.</li><li><strong>DEV-03:</strong> Agent attempted to kill the background node process using <code>fuser</code> and <code>kill</code>, but failed to use valid flags or properly inject the tools.</li><li><strong>DEV-05:</strong> Agent patched package.json to remove <code>tsc</code> instead of installing it, resulting in runtime errors for missing dist directory that it could not recover from.</li></ul><h2 id="_10-agentic-necessity" tabindex="-1">10. Agentic Necessity <a class="header-anchor" href="#_10-agentic-necessity" aria-label="Permalink to &quot;10. Agentic Necessity&quot;">​</a></h2><p><strong>Does the iterative OpenAI agent materially outperform the one-shot baseline?</strong> Yes. In <code>DEV-04</code> (Hidden CRLF Bash entrypoint), the Baseline blindly assumed a permissions error. The Agent iteratively used <code>file ./entrypoint.sh</code>, identified the CRLF line endings, and surgically used <code>patch_file</code> to replace the shebang line with standard <code>\\n</code>, successfully fixing the container and passing the Verifier.</p><h2 id="_11-architecture-decision" tabindex="-1">11. Architecture Decision <a class="header-anchor" href="#_11-architecture-decision" aria-label="Permalink to &quot;11. Architecture Decision&quot;">​</a></h2><p><strong>PASS</strong>. The Node.js + Structured Tool-Calling Controller + Docker Sandbox proved to be a Grade A architecture capable of producing real autonomous repairs.</p><h2 id="_12-recommended-next-step" tabindex="-1">12. Recommended Next Step <a class="header-anchor" href="#_12-recommended-next-step" aria-label="Permalink to &quot;12. Recommended Next Step&quot;">​</a></h2><p>Proceed to Phase 4 (Hackathon Product Construction) using a Pay-as-You-Go API Key.</p>',26)])])}const y=e(r,[["render",l]]);export{u as __pageData,y as default};
